const source = $('Official Source Registry').item.json;
const response = $input.item.json;
const raw = typeof response === 'string' ? response : String(response.data ?? response.body ?? JSON.stringify(response));
const out = []; const seen = new Set();
const allowed = /penalt|enforce|disciplin|sanction|contravention|anti[- ]?money|money[- ]?launder|administrative|prosecution|罚款|处罚|反洗钱|行政处罚|监管措施|纪律处分|执法/i;
const push = (urlValue,titleValue,dateValue=null) => {
  let parsed; try { parsed = new URL(String(urlValue || ''), source.url); } catch { return; }
  if (parsed.protocol !== 'https:') return;
  const host = parsed.hostname.toLowerCase();
  if (!source.allowedDomains.some(d => host === d || host === 'www.' + d || host.endsWith('.' + d))) return;
  parsed.hash = '';
  const url = parsed.href; const title = String(titleValue || '').replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/\s+/g,' ').trim();
  if (!title || !allowed.test(title + ' ' + url) || seen.has(url)) return;
  seen.add(url);
  out.push({json:{...source,source_page:source.url,url,title,publication_date:dateValue || null,discovered_at:new Date().toISOString(),pipeline_version:'regintel-n8n-v1'}});
};
if (source.mode === 'json') {
  try {
    const payload = typeof response === 'object' && response.result ? response : JSON.parse(raw);
    const records = payload?.result?.records || payload?.data || payload?.records || [];
    for (const record of records) push(record.url || record.link || record.hyperlink, record.title_en || record.title || record.name, record.press_release_date || record.publish_date || record.date);
  } catch (error) { throw new Error('Official JSON adapter failed for ' + source.source_code + ': ' + error.message); }
} else {
  for (const match of raw.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) push(match[1].replace(/&amp;/g,'&'), match[2]);
}
return out.slice(0, 60);

const candidate = $('Discover Official Candidates').item.json;
const response = $input.item.json;
const raw = typeof response === 'string' ? response : String(response.data ?? response.body ?? '');
const officialText = raw.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim().slice(0,50000);
const query = `${candidate.regulator} ${candidate.title} ${candidate.jurisdiction === 'CN' ? '行政处罚 监管 执法' : 'enforcement disciplinary penalty'}`.slice(0,500);
return [{json:{...candidate,official_text:officialText,anysearch_query:query,document_type:'official_announcement',verification_status:'unverified'}}];

const candidate = $('Build Verification Package').item.json;
const search = $input.item.json || {};
const results = search.results || search.data || search.items || [];
const evidence = (Array.isArray(results) ? results : []).slice(0,5).map(r => ({title:r.title || r.name || '',url:r.url || r.link || '',snippet:r.snippet || r.description || r.content || '',source:r.source || ''}));
const schema = {relevance:'enforcement|not_enforcement|uncertain',case_type:'fine|warning|improvement_order|suspension|revocation|prohibition|prosecution|other',entity_names:[],decision_date:null,publication_date:null,violations:[{verbatim_wording:'',normalized_category:'AML_CFT|KYC_CDD|EDD|BENEFICIAL_OWNERSHIP|SANCTIONS_SCREENING|TRANSACTION_MONITORING|STR_SAR|RECORDKEEPING|GOVERNANCE|MARKET_CONDUCT|FX|PAYMENTS|OTHER',legal_citation:'',classification_basis:'confirmed_by_regulator|analyst_inference',confidence:0}],penalties:[{penalty_type:'',currency:null,amount:null,original_amount_text:'',combined_amount:false,amount_allocation_status:'not_applicable|explicit|unallocated_composite|needs_review',evidence_span:''}],control_findings:[{control_domain:'',observed_failure:'',possible_root_cause:'',classification:'confirmed_by_regulator|analyst_inference',evidence_span:'',confidence:0}],summary_en:'',summary_cn:'',confidence:0,missing_fields:[],review_notes:''};
const instructions = `You are a regulatory enforcement intelligence analyst. Return JSON only. Treat the official regulator text as primary evidence. Search results are corroboration only and may be wrong. Do not invent facts, dates, legal citations, entities, amounts, currencies, or control failures. Preserve exact original-currency amounts. Never assign an entire composite fine to AML unless the regulator explicitly apportions it. Mark inferred control findings as analyst_inference. Do not set verified or published status. If the text is not a formal regulator/court/enforcement action, classify it not_enforcement. Required JSON shape: ${JSON.stringify(schema)}`;
const content = {source_code:candidate.source_code,jurisdiction:candidate.jurisdiction,regulator:candidate.regulator,official_url:candidate.url,title:candidate.title,publication_date:candidate.publication_date,official_text:candidate.official_text,corroboration:evidence};
return [{json:{...candidate,anysearch_evidence:evidence,ai_request:{model:'deepseek-chat',temperature:0,response_format:{type:'json_object'},messages:[{role:'system',content:instructions},{role:'user',content:JSON.stringify(content)}]}}}];

const base = $('Build Strict AI Analysis').item.json;
const response = $input.item.json || {};
let analysis = {};
try {
  const text = response?.choices?.[0]?.message?.content ?? response?.output_text ?? '';
  analysis = typeof text === 'object' ? text : JSON.parse(String(text).replace(/^```json\s*|```$/g,'').trim());
} catch (error) { analysis = {relevance:'uncertain',confidence:0,missing_fields:['ai_analysis'],review_notes:'AI analysis unavailable or invalid JSON: ' + error.message}; }
const allowedRelevance = ['enforcement','not_enforcement','uncertain'];
if (!allowedRelevance.includes(analysis.relevance)) analysis.relevance = 'uncertain';
analysis.confidence = Math.max(0,Math.min(1,Number(analysis.confidence || 0)));
delete analysis.verification_status; delete analysis.review_status; delete analysis.published;
return [{json:{source_code:base.source_code,jurisdiction:base.jurisdiction,regulator:base.regulator,source_page:base.source_page,url:base.url,title:base.title,publication_date:base.publication_date,discovered_at:base.discovered_at,language:base.language,official_text:base.official_text,document_type:'official_announcement',verification_status:'unverified',pipeline_version:'regintel-n8n-v1',workflow_execution_id:$execution.id,anysearch_evidence:base.anysearch_evidence,ai_analysis:analysis}}];
